export type OwnedKind = "annotation" | "track";

export type EntityKind = "member" | "plate" | "shell" | "solid" | "fastener" | "support" | "load" | "surface" | "group";

export type PickPolicy = "whole" | "vertex" | "edge" | "face" | "none";

export type EndRelease = "rigid" | "pinned" | "sliding" | "free";

export type HeadShape = "hex" | "countersunk" | "round" | "headed" | "none";

export type WeldKind = "fillet" | "butt";

export type Geometry =
  | { kind: "member"; data: MemberGeometry }
  | { kind: "plate"; data: PlateGeometry }
  | { kind: "shell"; data: ShellGeometry }
  | { kind: "solid"; data: SolidGeometry }
  | { kind: "fastener"; data: FastenerGeometry }
  | { kind: "support"; data: SupportGeometry }
  | { kind: "load"; data: LoadGlyph }
  | { kind: "surface"; data: SurfaceGeometry }
  | { kind: "group"; data: { members: EntityRef[] } };

export type ShellShape =
  | { kind: "revolved"; data: { origin: Vec3; axis: Vec3; generatrix: Polyline2; sweep: number } }
  | { kind: "patch"; data: { grid: PointGrid } };

export type SolidShape =
  | { kind: "prism"; data: { frame: Frame; base: Polygon2; height: number } }
  | { kind: "box"; data: { frame: Frame; size: Vec3 } }
  | { kind: "cylinder"; data: { frame: Frame; radius: number; height: number } }
  | { kind: "wedge"; data: { frame: Frame; base: Vec2; height: number } }
  | { kind: "mesh"; data: { vertices: Vec3[]; triangles: Triangle[] } }
  | { kind: "strataColumn"; data: { frame: Frame; footprint: Polygon2; strata: Stratum[] } }
  | { kind: "footingBody"; data: { frame: Frame; footprint: Polygon2; thickness: number; pedestal: Vec2 | null; pedestalHeight: number } }
  | { kind: "wallAssembly"; data: { path: Polyline3; height: number; layers: WallLayer[]; openings: WallCut[] } }
  | { kind: "laminate"; data: { frame: Frame; footprint: Polygon2; layers: GrainLayer[] } };

export type FastenerKind =
  | { kind: "bolt"; data: { class: string; preload: Quantity | null } }
  | { kind: "screw" }
  | { kind: "nail" }
  | { kind: "dowel" }
  | { kind: "stud"; data: { headHeight: number; headDiameter: number } }
  | { kind: "rebar"; data: { bend: BendShape | null } }
  | { kind: "anchor" }
  | { kind: "weld"; data: { throat: number; weld: WeldKind } }
  | { kind: "weldRun"; data: { throat: number; weld: WeldKind; path: Path3; pitch: WeldPitch | null } }
  | { kind: "tendon"; data: { profile: Path3; duct: number | null } };

export type Pattern =
  | { kind: "grid"; data: { nx: number; ny: number; sx: number; sy: number } }
  | { kind: "row"; data: { n: number; s: number } }
  | { kind: "along"; data: { path: Path3; spacing: number } }
  | { kind: "cage"; data: { outline: Ring2; zones: LinkZone[]; reference: Vec3 } }
  | { kind: "points"; data: { offsets: Vec3[] } };

export type SurfaceShape =
  | { kind: "polygon"; data: { polygon: Polygon3 } }
  | { kind: "arc"; data: { arc: Arc; width: number } }
  | { kind: "grid"; data: { grid: PointGrid } };

export interface Legend {
  id: string;
  title: LocalizedCopy;
  scale: LegendScale;
}

export interface LegendRole {
  role: MaterialRole;
  label: LocalizedCopy;
}

export type Tone = "neutral" | "info" | "warning" | "error";

export type FailureMode = "lateralTorsionalBuckling" | "flexuralBuckling" | "yielding" | "crushing" | "punching" | "slipCircle" | "shearCone" | "blockTearOut" | "overturning" | "sliding" | "fatigue" | "other";

export type Annotation =
  | { kind: "dimension"; data: { id: string; from: Vec3; to: Vec3; offset: Vec3; value: Quantity; binding: FieldBinding | null } }
  | { kind: "label"; data: { id: string; anchor: Vec3; text: LocalizedCopy; tone: Tone } }
  | { kind: "leader"; data: { id: string; anchor: Vec3; text: LocalizedCopy; offsetPx: number[] } }
  | { kind: "clause"; data: { id: string; anchor: EntityRef; clause: ClauseId } }
  | { kind: "failureGlyph"; data: { id: string; at: EntityRef; mode: FailureMode; extent: Polygon3 | null } };

export type LegendScale =
  | { kind: "utilisation"; data: { map: ColourMapRef } }
  | { kind: "roles"; data: { entries: LegendRole[] } }
  | { kind: "scalar"; data: { fieldId: string; map: ColourMapRef; unit: QuantityKind } };

export interface SceneDelta {
  base: SceneRevision;
  revision: SceneRevision;
  bounds: Aabb | null;
  entities: EntityPatch[];
  annotations: AnnotationPatch[];
  legends: Legend[] | null;
  layers: Layer[] | null;
  tracks: ParameterTrack[] | null;
  owners: Ownership[] | null;
  description: LocalizedCopy | null;
}

export type EntityPatch =
  | { kind: "add"; data: { index: number; entity: SceneEntity } }
  | { kind: "replace"; data: { entity: SceneEntity } }
  | { kind: "remove"; data: { id: string } };

export type AnnotationPatch =
  | { kind: "add"; data: { index: number; annotation: Annotation } }
  | { kind: "replace"; data: { annotation: Annotation } }
  | { kind: "remove"; data: { id: string } };

export interface Violation {
  path: string;
  rule: string;
}

